/**
 * Release signing for local builds (no EAS). `android/` is regenerated by `expo prebuild`, so the release
 * signingConfig is injected into android/app/build.gradle here.
 *
 * Nothing secret is written: the generated Gradle reads these at build time, from environment variables or
 * ~/.gradle/gradle.properties:
 *   DIME_UPLOAD_STORE_FILE, DIME_UPLOAD_STORE_PASSWORD, DIME_UPLOAD_KEY_ALIAS, DIME_UPLOAD_KEY_PASSWORD
 * When the keystore is not configured the release build falls back to debug signing and prints a loud warning
 * (that APK cannot update an install signed with the real key).
 */
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// dime-release-signing";

const HELPERS = `${MARKER}
def dimeProp = { String name -> System.getenv(name) ?: findProperty(name) }
def dimeStoreFile = dimeProp('DIME_UPLOAD_STORE_FILE')
def dimeHasReleaseKey = dimeStoreFile && new File(dimeStoreFile).exists()
if (!dimeHasReleaseKey) {
    logger.warn("!!! DIME: DIME_UPLOAD_STORE_FILE is not set or the file is missing. The release build is signed with the DEBUG key. Do not distribute it. See docs/RELEASE.md. !!!")
}

`;

const RELEASE_CONFIG = `
        release {
            if (dimeHasReleaseKey) {
                storeFile new File(dimeStoreFile)
                storePassword dimeProp('DIME_UPLOAD_STORE_PASSWORD')
                keyAlias dimeProp('DIME_UPLOAD_KEY_ALIAS')
                keyPassword dimeProp('DIME_UPLOAD_KEY_PASSWORD')
            }
        }`;

/** Pure string transform (exported for tests). Idempotent. */
function applyReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents;
  if (!/signingConfigs\s*\{/.test(contents) || !/\n\s*android\s*\{/.test(contents)) {
    throw new Error("withReleaseSigning: unexpected android/app/build.gradle layout");
  }
  let out = contents.replace(/\n(\s*)android\s*\{/, (m, ws) => `\n${HELPERS}${ws}android {`);
  // Add `release` after the debug signing config block.
  out = out.replace(/(signingConfigs\s*\{[\s\S]*?debug\s*\{[\s\S]*?\n\s*\})/, `$1${RELEASE_CONFIG}`);
  // Point the release build type at it (debug fallback), leaving the debug build type alone.
  out = out.replace(
    /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
    "$1signingConfig dimeHasReleaseKey ? signingConfigs.release : signingConfigs.debug",
  );
  if (!out.includes("signingConfigs.release")) {
    throw new Error("withReleaseSigning: could not wire the release buildType");
  }
  return out;
}

module.exports = (config) =>
  withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
module.exports.applyReleaseSigning = applyReleaseSigning;
